sys_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below

       if (g_form.getViewName() === 'Requestor View') {

        // 2. Define your two-line message string
        var message = "Please provide a clear reason why this item is required.\n" +
                      "Justification helps in quicker approval and proper fulfillment.";

        // 3. Display the message underneath the justification field
        // Replace 'justification' with the actual database/backend name of your field
        g_form.showFieldMsg('justification', message, 'info'); 
    }
}
